<style>
.button-login-daftar{display:grid;grid-template-columns:repeat(2,1fr);font-weight:700;gap:12px;margin:15px 0}
.button-login-daftar a{text-align:center;text-decoration:none;border-radius:12px;transition:all .3s ease;position:relative;overflow:hidden}
.login,.register{color:#2A0A22;padding:15px 10px;font-size:15px;font-family:'Plus Jakarta Sans','Orbitron',sans-serif;font-weight:800;text-shadow:0 1px 2px rgba(255,255,255,.5);letter-spacing:.4px}
.login,.login-button{background:linear-gradient(135deg,#FFF0F8 0%,#FFB3DC 25%,#FF7BC8 55%,#FF2E9A 100%);border:2px solid #FF7BC8;box-shadow:inset 0 2px 3px rgba(255,255,255,.85),0 6px 16px rgba(255,46,154,.3),0 0 12px rgba(255,123,200,.18)}
.register,.register-button{background:linear-gradient(135deg,#FFE0F2 0%,#FFC4E6 25%,#FF7BC8 55%,#FF2E9A 100%);border:2px solid #FFC4E6;box-shadow:inset 0 2px 3px rgba(255,255,255,.9),0 6px 16px rgba(255,46,154,.3),0 0 12px rgba(255,123,200,.2)}
.login:hover,.login-button:hover{background:linear-gradient(135deg,#FFE0F2 0%,#FF7BC8 40%,#FF2E9A 100%);color:#2A0A22;transform:translateY(-3px);box-shadow:inset 0 1px 3px rgba(255,255,255,.9),0 9px 22px rgba(255,46,154,.45),0 0 18px rgba(255,123,200,.3)}
.register:hover,.register-button:hover{background:linear-gradient(135deg,#FFE0F2 0%,#FFC4E6 40%,#C2189B 100%);color:#2A0A22;transform:translateY(-3px);box-shadow:inset 0 1px 3px rgba(255,255,255,.9),0 9px 22px rgba(255,46,154,.45),0 0 18px rgba(255,123,200,.3)}
.login:focus-visible,.register:focus-visible,.login-button:focus-visible,.register-button:focus-visible{outline:3px solid #2A0A22;outline-offset:3px}
@media(max-width:480px){.button-login-daftar{gap:8px;margin:12px 0}.login,.register{padding:13px 8px;font-size:14px}}
