<script>
(() => {
  // ---------- Asset foto profil user biasa (pria & wanita) ----------
  // Menggunakan penyedia avatar pihak ketiga yang stabil dan gratis
  const AVATARS = [
    "https://i.pravatar.cc/100?img=11",
    "https://i.pravatar.cc/100?img=12",
    "https://i.pravatar.cc/100?img=32",
    "https://i.pravatar.cc/100?img=33",
    "https://i.pravatar.cc/100?img=47",
    "https://i.pravatar.cc/100?img=53",
    "https://i.pravatar.cc/100?img=59",
    "https://i.pravatar.cc/100?img=60",
    "https://i.pravatar.cc/100?img=64",
    "https://i.pravatar.cc/100?img=68"
  ];

  // ---------- Helper ----------
  const rand = (a,b)=> Math.floor(Math.random()*(b-a+1))+a;
  const formatIDR = n => "IDR " + n.toLocaleString("en-US",{minimumFractionDigits:2, maximumFractionDigits:2});
  const mask = name => {
    const s = name.toLowerCase();
    if (s.length <= 2) return s[0]+"*";
    return s.slice(0,2) + "****" + s.slice(-1);
  };

  const macauGames = [
    {title: "LINK ALTERNATIF IBIZA168", minWin: 4000000, maxWin: 10000000},
    {title: "AKSES CEPAT IBIZA168", minWin: 400000, maxWin: 1000000},
    {title: "DAFTAR IBIZA168", minWin: 70000, maxWin: 200000},
    {title: "LOGIN IBIZA168", minWin: 30000, maxWin: 150000},
    {title: "AKSES TERBARU IBIZA168", minWin: 500000, maxWin: 2500000},
    {title: "REGIST IBIZA168", minWin: 100000, maxWin: 950000},
    {title: "PANEL IBIZA168", minWin: 150000, maxWin: 800000},
    {title: "LOGIN IBIZA168", minWin: 200000, maxWin: 1600000}
  ];

  const names = ["mazi","athar","lazu","niko","bima","saka","dion","raka","alva","vino","kazu","aryo","fiko","rino","reva"];

  function winner() {
    const g = macauGames[rand(0, macauGames.length - 1)];
    const totalWin = rand(g.minWin, g.maxWin);
    // Mengambil foto profil orang secara acak dari list di atas
    const userImg = AVATARS[rand(0, AVATARS.length - 1)];

    return {
      name: mask(names[rand(0,names.length-1)]) + rand(0,9),
      amount: totalWin,
      game: g.title,
      img: userImg
    };
  }

  const track = document.getElementById('wbTrack');

  // build initial 8 rows
  const LIST_SIZE = 8;
  for (let i=0;i<LIST_SIZE;i++){
    track.appendChild(renderItem(winner()));
  }

  // animasi scroll 1 per 2.8 detik
  const STEP_MS = 2800;
  let itemH = null, ticking = false;
  setTimeout(()=>{ // delay sedikit agar layout fix
    itemH = track.children[0].offsetHeight + 10; // +gap
    cycle();
    setInterval(cycle, STEP_MS);
  }, 150);

  function cycle(){
    if (ticking) return;
    ticking = true;

    // Tandai kandidat yang akan jadi teratas (elemen index 1)
    const upcoming = track.children[1];
    if (upcoming) upcoming.classList.add('is-new');

    // Geser track ke atas setinggi 1 item
    track.style.transition = "transform .6s ease";
    track.style.transform = `translateY(-${itemH}px)`;

    // setelah transisi: rotasi node
    track.addEventListener('transitionend', onEnd, {once:true});

    function onEnd(){
      track.style.transition = "none";
      track.style.transform = "translateY(0)";
      // pindah elemen pertama ke bawah, sebagai loop
      track.appendChild(track.firstElementChild);
      // Hapus flag is-new dari semua selain sekarang paling atas
      [...track.children].forEach((li,i)=> li.classList.toggle('is-new', i===0));
      // hitung amount naik (count-up) di item teratas
      animateCount(track.children[0].querySelector('[data-amount]'));

      // Tambahkan pemenang baru secara periodik agar list variatif
      if (rand(0,2)===1) {
        // replace salah satu elemen random di bawah dengan pemenang baru
        const idx = rand(2, track.children.length-1);
        track.replaceChild(renderItem(winner()), track.children[idx]);
      }

      // koin spark di sekitar panel
      sprinkleCoins();

      ticking = false;
    }
  }

  function renderItem({name, amount, game, img}){
    const li = document.createElement('li');
    li.className = 'wb-item';
    li.innerHTML = `
      <img class="wb-thumb" src="${img}" alt="" style="border-radius: 50%;">
      <div>
        <div class="wb-name">${name}</div>
        <div class="wb-amount" data-amount="${amount}">${formatIDR(amount)}</div>
        <div class="wb-game">${game}</div>
      </div>
    `;
    return li;
  }

  // count-up angka untuk item teratas
  function animateCount(el){
    if (!el) return;
    const target = +el.dataset.amount;
    let start = Math.max(10_000, Math.floor(target*0.7));
    const dur = 650, fps = 30;
    const step = Math.max(1, Math.floor((target-start)/(dur/fps)));
    const timer = setInterval(()=>{
      start += step;
      if (start >= target){ start = target; clearInterval(timer); }
      el.textContent = formatIDR(start);
    }, 1000/fps);
  }

  // efek koin kecil
  function sprinkleCoins(){
    const box = document.getElementById('winnerBoard');
    if (!box) return; 
    const n = rand(3,6);
    for (let i=0;i<n;i++){
      const s = document.createElement('span');
      s.className = 'wb-coin';
      s.style.left = (rand(20, box.offsetWidth-20))+'px';
      s.style.bottom = (rand(10, 40))+'px';
      s.style.setProperty('--sx', (Math.random()>.5?1:-1)*rand(6,12)+'px');
      box.appendChild(s);
      setTimeout(()=> s.remove(), 900);
    }
  }
})();
</script>
<!-- ============ WINNER LEADERBOARD Ã¢â‚¬Â¢ MAROONÃ¢â‚¬â€œGOLD (AUTO SCROLL) ============ -->

<style>
:root{--ug-deep:#FFF0F8;--ug-deeper:#FFC4E6;--ug-acc:#FF2E9A;--ug-acc-2:#FFC4E6;--line:rgba(255,46,154,.38);--glass:rgba(255,46,154,.09);--txt:#2A0A22;--muted:#8A3A72}
.wb-panel{width:340px;background:linear-gradient(160deg,#FFFFFF 0%,var(--ug-deep) 35%,#FFE0F2 70%,var(--ug-deeper) 100%);border:1px solid var(--line);border-radius:16px;color:var(--txt);font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;box-shadow:0 12px 28px rgba(255,46,154,.15),0 0 22px rgba(255,46,154,.12),inset 0 1px 2px rgba(255,255,255,.9);overflow:hidden;position:relative}
.wb-head{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line);background:radial-gradient(120% 140% at 0% 0%,rgba(255,46,154,.2),transparent 55%),linear-gradient(135deg,#FFFFFF 0%,#FFC4E6 65%,#FFE0F2 100%)}
.wb-trophy{width:20px;height:20px;flex:0 0 20px;color:#2A0A22;background:linear-gradient(135deg,#FFE0F2 0%,#FF7BC8 45%,#FF2E9A 100%);border:1px solid rgba(194,24,155,.3);border-radius:6px;display:grid;place-items:center;box-shadow:0 4px 12px rgba(255,46,154,.25),0 0 10px rgba(255,46,154,.15)}
.wb-title{font:900 13px/1.1 system-ui;letter-spacing:.35px;text-transform:uppercase;color:#C2189B;text-shadow:0 1px 2px rgba(255,255,255,.8)}
.wb-dot{margin-left:auto;width:9px;height:9px;border-radius:50%;background:radial-gradient(circle,#FFFFFF 0%,#FFB3DC 35%,#FF2E9A 75%,#C2189B 100%);box-shadow:0 0 10px rgba(255,46,154,.65),0 0 5px rgba(255,46,154,.3);animation:wbPing 1.8s ease-in-out infinite}
@keyframes wbPing{0%,100%{transform:scale(1)}50%{transform:scale(1.25)}}
.wb-list-wrap{height:280px;overflow:hidden;position:relative;-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 8%,#000 92%,transparent 100%);mask-image:linear-gradient(to bottom,transparent 0,#000 8%,#000 92%,transparent 100%);background:linear-gradient(180deg,var(--glass),rgba(255,255,255,.2) 50%,transparent)}
.wb-track{list-style:none;margin:0;padding:8px 10px 10px;display:flex;flex-direction:column;gap:10px;will-change:transform}
.wb-item{display:grid;grid-template-columns:52px 1fr;gap:10px;padding:8px;border-radius:12px;position:relative;isolation:isolate;border:1px solid rgba(255,46,154,.3);background:linear-gradient(135deg,#FFFFFF 0%,#FFF0F8 50%,#FFC4E6 100%);box-shadow:inset 0 1px 2px rgba(255,255,255,.95),0 3px 10px rgba(255,46,154,.09)}
.wb-thumb{width:52px;height:52px;border-radius:10px;object-fit:cover;display:block;border:1px solid rgba(255,46,154,.4);box-shadow:0 2px 8px rgba(255,46,154,.12)}
.wb-name{font:800 12px/1.1 system-ui;letter-spacing:.2px;margin:0 0 4px;color:#2A0A22}
.wb-amount{font:900 13px/1 system-ui;color:#C2189B;text-shadow:0 1px 2px rgba(255,255,255,.8)}
.wb-game{font:600 11px/1.2 system-ui;color:#8A3A72;margin-top:4px;opacity:.95}
.wb-item.is-new{box-shadow:0 10px 24px rgba(255,46,154,.18),0 0 18px rgba(255,46,154,.15),inset 0 0 0 1px rgba(255,255,255,.7);border-color:#FF2E9A;transform:translateZ(0);animation:wbPulse 1.2s ease both}
@keyframes wbPulse{0%{filter:saturate(1)}40%{filter:saturate(1.12)}100%{filter:saturate(1.05)}}
.wb-coin{position:absolute;width:12px;height:12px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#FFFFFF 0%,#FFE0F2 25%,#FFC4E6 50%,#FF2E9A 75%,#C2189B 100%);border:1px solid rgba(255,255,255,.7);box-shadow:0 0 10px rgba(255,46,154,.45),0 0 6px rgba(255,46,154,.2);pointer-events:none;z-index:5;animation:coinPop .9s ease-out forwards}
@keyframes coinPop{0%{transform:translate(var(--sx,0),14px) scale(.6) rotate(0);opacity:.95}70%{transform:translate(calc(var(--sx,0)*1.2),-20px) scale(1) rotate(120deg);opacity:1}100%{transform:translate(calc(var(--sx,0)*2),-36px) scale(.85) rotate(240deg);opacity:0}}
.wb-foot{border-top:1px solid var(--line);padding:9px 12px;font:600 11px/1.2 system-ui;color:#6E0F52;display:flex;gap:8px;align-items:center;background:linear-gradient(90deg,#FFF0F8 0%,#FFE0F2 65%,#FFE0F2 100%)}
.wb-pill{margin-left:auto;border:1px solid #FF2E9A;color:#2A0A22;background:linear-gradient(135deg,#FFE0F2 0%,#FFC4E6 45%,#FF2E9A 100%);border-radius:999px;font:800 10px/1 system-ui;padding:6px 10px;box-shadow:0 4px 12px rgba(255,46,154,.22),inset 0 1px 2px rgba(255,255,255,.9)}
@media(max-width:480px){.wb-panel{width:92vw}}
</style>

